//! Shared type names declared by the CORE setting.
//!
//! Rakudo resolves a bareword against the setting at parse time. A name that
//! is a type object there, such as `X::AdHoc` or `IO::Path`, renders as
//! `Type::Simple` (measured on 2026.09). mutsu's parser leaves it as
//! `Expr::BareWord`, so conversion and execution share the setting's type names
//! rather than manufacturing unknown qualified packages. `core_type_names.txt` is generated by
//! `scripts/gen-core-type-names.raku`; regenerate it rather than editing it.
//! `python3 scripts/gen-core-type-additions.py` generates the preview-only
//! additions in `core_type_names_6e.txt` by comparing one Rakudo's two settings.

use std::collections::HashSet;
use std::sync::LazyLock;

static NAMES: LazyLock<HashSet<&'static str>> = LazyLock::new(|| {
    include_str!("core_type_names.txt")
        .lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .collect()
});

/// Whether `name` is a type the CORE setting declares.
// Cost: O(k), k = length of `name` (one hash lookup; the set is built once).
pub(crate) fn contains(name: &str) -> bool {
    NAMES.contains(name)
}

/// Additional setting types available when the unit selects 6.e.
// Cost: O(k), k = name length; the generated set is initialized once.
pub(crate) fn contains_in_version(name: &str, preview: bool) -> bool {
    static PREVIEW: LazyLock<HashSet<&'static str>> = LazyLock::new(|| {
        include_str!("core_type_names_6e.txt")
            .lines()
            .filter(|line| !line.is_empty() && !line.starts_with('#'))
            .collect()
    });
    contains(name) || (preview && PREVIEW.contains(name))
}

#[cfg(test)]
mod tests {
    use super::contains;

    #[test]
    fn knows_setting_types_and_not_terms() {
        assert!(contains("Int"));
        assert!(contains("X::AdHoc"));
        assert!(contains("IO::Socket::Async"));
        // A defined constant is a `Term::Name`, not a type.
        assert!(!contains("IterationEnd"));
        assert!(!contains("NoSuchType"));
    }

    #[test]
    fn preview_additions_do_not_enter_the_default_setting() {
        for name in [
            "Format",
            "Formatter",
            "Formatter::Syntax",
            "Metamodel::v6e::GrammarHOW",
        ] {
            assert!(!super::contains_in_version(name, false));
            assert!(super::contains_in_version(name, true));
        }
        assert!(super::contains_in_version("Int", true));
        assert!(!super::contains_in_version("NoSuchType", true));
    }
}
